@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/quick-add")
public class QuickAddController {

    /** A quick-add: the person's name (not blank) and the claim's amount, 0.00 or more with up to
     *  two decimals. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal amount) {
    }

    /** The person the claim is for, as stored now, and the claim added. */
    public record QuickAddView(PersonView person, ClaimView claim) {
    }

    private final QuickAddService service;
    private final StatementService statements;

    public QuickAddController(QuickAddService service, StatementService statements) {
        this.service = service;
        this.statements = statements;
    }

    /** Add a DRAFT claim for the named person, adding them first when the name is not on the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public QuickAddView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated QuickAddRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        QuickAddService.Added added = service.add(sheet, by, request.name(), request.amount());
        return new QuickAddView(PersonView.of(added.person(), statements.summary(sheet, added.person().getId())),
                ClaimView.of(added.claim()));
    }

    /** A claim dated in a closed period, or a name taken at the same moment, is refused. */
    @ExceptionHandler({PeriodClosedException.class, NameInUseException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** An amount that is not a number is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim for a person named on the sheet, adding the person first (grade A) when the
 *  name is not on it. The whole quick-add is one change: a refused claim leaves no person behind. */
@Service
public class QuickAddService {

    /** The grade a person added by a quick-add takes. */
    private static final String GRADE = "A";

    /** A quick-add's result: the person the claim is for and the claim added. */
    public record Added(Person person, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claims;
    private final RollupService rollups;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claims,
            RollupService rollups) {
        this.people = people;
        this.personService = personService;
        this.claims = claims;
        this.rollups = rollups;
    }

    /** Add a claim of the amount, dated the sheet's today with an empty note, for the named person. */
    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = rollups.track(sheetId, user, () -> people.findByName(sheetId, trimmed)
                .orElseGet(() -> personService.add(sheetId, user, trimmed, GRADE)));
        Claim claim = rollups.track(sheetId, user, () -> claims.add(sheetId, user, person.getId(), amount, null, ""));
        return new Added(person, claim);
    }
}
